'use strict';
const labels={unknown:'ยังไม่มีข้อมูลล่าสุด',clear:'รายงานว่าไม่พบน้ำ',flood:'มีรายงานน้ำท่วม',closed:'ปิดถนน / อันตราย'};
const colors={unknown:'#87979f',clear:'#22966d',flood:'#dda822',closed:'#dc514d'};
let reports={};try{reports=JSON.parse(localStorage.getItem('klaeng-demo-reports-v1')||'{}')}catch{}
let collection=null,selected=null,pinning=false;
const detail=document.getElementById('detail');
function state(f){const r=reports[f.properties.key];return r&&Date.now()-r.time<3600000?r.status:'unknown'}
function decorate(){for(const f of collection.features)f.properties.status=state(f);map.getSource('roads')?.setData(collection)}
function html(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e}
function choose(f){selected=collection.features.find(x=>x.id===f.id);if(!selected)return;map.setFilter('selected-shadow',['==',['id'],selected.id]);map.setFilter('selected-road',['==',['id'],selected.id]);showDetail()}
function unselect(){selected=null;map.setFilter('selected-shadow',['==',['id'],-1]);map.setFilter('selected-road',['==',['id'],-1]);detail.replaceChildren(html('h2','','เลือกถนนบนแผนที่'),html('p','note','ซูมเข้าแล้วจิ้มช่วงถนนที่ต้องการดู'))}
function showDetail(){const f=selected,r=reports[f.properties.key],s=state(f);detail.replaceChildren();const top=html('div','detail-top');top.append(html('h2','',f.properties.name+(f.properties.ref?' · '+f.properties.ref:'')));const close=html('button','secondary','ปิด');close.type='button';close.onclick=unselect;top.append(close);detail.append(top);const badge=html('div','status');const dot=html('b');dot.style.background=colors[s];badge.append(dot,document.createTextNode(labels[s]));detail.append(badge);
const meta=html('div','meta');meta.textContent=r?'พบเห็น: '+new Date(r.time).toLocaleString('th-TH')+(state(f)==='unknown'?' · ข้อมูลเก่าแล้ว':''):'ยังไม่มีรายงานสำหรับช่วงนี้';detail.append(meta);if(r?.note)detail.append(html('p','note',r.note));detail.append(html('p','note','ข้อมูลถนน: OpenStreetMap · ช่วงระหว่างจุดเชื่อมถนน'));
const form=html('form');const slabel=html('label','','สภาพที่พบเห็น');slabel.htmlFor='status';const select=html('select');select.id='status';select.required=true;select.append(new Option('เลือกสภาพถนน',''));for(const k of ['clear','flood','closed'])select.append(new Option(labels[k],k));const tlabel=html('label','','เวลาที่พบเห็น');tlabel.htmlFor='observed';const time=html('input');time.id='observed';time.type='datetime-local';time.required=true;const local=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);time.value=local;time.max=local;const nlabel=html('label','','รายละเอียดเพิ่มเติม (ไม่บังคับ)');nlabel.htmlFor='note';const note=html('textarea');note.id='note';note.rows=2;note.maxLength=300;note.placeholder='เช่น หน้าตลาด น้ำกำลังเพิ่ม';const button=html('button','primary','บันทึกรายงานทดลอง');button.type='submit';const message=html('div');message.id='message';message.setAttribute('role','status');form.append(slabel,select,tlabel,time,nlabel,note,button,message);form.onsubmit=e=>{e.preventDefault();const ts=new Date(time.value).getTime();if(!labels[select.value]||select.value==='unknown'||!Number.isFinite(ts)||ts>Date.now()){message.className='error';message.textContent='โปรดเลือกสถานะและเวลาที่ไม่ใช่อนาคต';return}const next={...reports,[f.properties.key]:{status:select.value,time:ts,note:note.value.trim()}};try{localStorage.setItem('klaeng-demo-reports-v1',JSON.stringify(next))}catch{message.className='error';message.textContent='บันทึกไม่ได้ พื้นที่เก็บข้อมูลของเครื่องอาจเต็ม';return}reports=next;decorate();showDetail();document.getElementById('message').textContent='บันทึกในเครื่องนี้แล้ว ยังไม่ได้ส่งให้ผู้อื่น'};detail.append(form)}
const map=new maplibregl.Map({container:'map',style:'https://tiles.openfreemap.org/styles/liberty',center:[101.648,12.779],zoom:13.4,attributionControl:true});map.addControl(new maplibregl.NavigationControl(),'top-right');
map.on('load',async()=>{try{const response=await fetch('roads.geojson');if(!response.ok)throw Error('roads');collection=await response.json();for(const f of collection.features)f.properties.status=state(f);map.addSource('roads',{type:'geojson',data:collection});const color=['match',['get','status'],'clear',colors.clear,'flood',colors.flood,'closed',colors.closed,colors.unknown];map.addLayer({id:'report-roads',type:'line',source:'roads',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':color,'line-width':['interpolate',['linear'],['zoom'],10,2,14,5,17,9],'line-opacity':.8}});map.addLayer({id:'road-hit',type:'line',source:'roads',paint:{'line-color':'#000','line-opacity':0,'line-width':24}});map.addLayer({id:'selected-shadow',type:'line',source:'roads',filter:['==',['id'],-1],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#173b35','line-width':15,'line-blur':5,'line-translate':[0,5],'line-opacity':.6}});map.addLayer({id:'selected-road',type:'line',source:'roads',filter:['==',['id'],-1],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':color,'line-width':9,'line-translate':[0,-3]}});map.on('click','road-hit',e=>{if(!pinning&&e.features.length)choose(e.features[0])});map.on('mouseenter','road-hit',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','road-hit',()=>map.getCanvas().style.cursor='');map.on('click',e=>{if(pinning){stageHelp(e.lngLat);return}if(!map.queryRenderedFeatures(e.point,{layers:['road-hit']}).length)unselect()});document.getElementById('loading').textContent=collection.features.length.toLocaleString('th-TH')+' ช่วงถนนจริง · เริ่มที่ตัวเมืองแกลง';registerTools();}catch{const loading=document.getElementById('loading');if(loading){loading.className='note error';loading.textContent='โหลดถนนไม่สำเร็จ โปรดลองเปิดใหม่'}}});
setInterval(()=>{if(collection){decorate();if(selected&&!detail.querySelector('form:focus-within'))showDetail()}},60000);
function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'select_road_segment',description:'Select a real road segment on the Klaeng prototype map. Does not submit a report.',inputSchema:{type:'object',properties:{segmentId:{type:'integer'}},required:['segmentId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({segmentId})=>{if(!Number.isInteger(segmentId))throw Error('Invalid segmentId');const f=collection.features.find(x=>x.id===segmentId);if(!f)throw Error('Road segment not found');choose(f);map.flyTo({center:f.geometry.coordinates[0],zoom:15,essential:false});return {segmentId,name:f.properties.name,status:labels[state(f)],demo:true}}})).catch(()=>{})}catch{}}

const helpButton=document.getElementById('help-pin');
helpButton.onclick=()=>{pinning=!pinning;helpButton.setAttribute('aria-pressed',String(pinning));helpButton.textContent=pinning?'แตะตำแหน่งบนแผนที่ · ยกเลิก':'ปักหมุดขอความช่วยเหลือ · ทดลอง';if(pinning){detail.replaceChildren(html('h2','','เลือกตำแหน่งที่ต้องการความช่วยเหลือ'),html('p','help-notice','หมุดทดลองนี้ยังไม่ส่งถึงหน่วยกู้ภัย หากเป็นเหตุจริง ให้ติดต่อหน่วยช่วยเหลือโดยตรง'))}else if(selected)showDetail();else detail.replaceChildren(html('h2','','เลือกถนนบนแผนที่'))};
function stageHelp(lngLat){pinning=false;helpButton.setAttribute('aria-pressed','false');helpButton.textContent='ปักหมุดขอความช่วยเหลือ · ทดลอง';selected=null;map.setFilter('selected-shadow',['==',['id'],-1]);map.setFilter('selected-road',['==',['id'],-1]);const element=html('button','help-marker','!');element.type='button';element.setAttribute('aria-label','หมุดขอความช่วยเหลือทดลอง');const marker=new maplibregl.Marker({element}).setLngLat(lngLat).addTo(map);
function renderHelp(){detail.replaceChildren(html('h2','','หมุดขอความช่วยเหลือ'),html('p','help-notice','ทดลองเท่านั้น · ไม่มีหน่วยกู้ภัยรับเรื่องจากหน้านี้'));const coords=html('p','meta','พิกัด '+lngLat.lat.toFixed(5)+', '+lngLat.lng.toFixed(5));detail.append(coords);const form=html('form');const label=html('label','','ความช่วยเหลือที่ต้องการ');label.htmlFor='need';const need=html('select');need.id='need';for(const text of ['อพยพออกจากพื้นที่','อาหาร / น้ำดื่ม','ยา / การดูแลผู้ป่วย','ความช่วยเหลืออื่น'])need.append(new Option(text,text));const countLabel=html('label','','จำนวนคน');countLabel.htmlFor='people';const count=html('input');count.id='people';count.type='number';count.min='1';count.max='1000';count.value='1';count.required=true;const save=html('button','primary','เก็บหมุดทดลอง');save.type='submit';const cancel=html('button','secondary','ลบหมุด');cancel.type='button';cancel.style.marginTop='12px';cancel.onclick=()=>{marker.remove();unselect()};const message=html('p','note');message.setAttribute('role','status');form.append(label,need,countLabel,count,save,message,cancel);form.onsubmit=e=>{e.preventDefault();save.disabled=true;save.textContent='เก็บหมุดทดลองแล้ว';message.textContent=need.value+' · '+count.value+' คน · อยู่เฉพาะหน้านี้ ไม่ได้ส่งคำขอจริง';element.setAttribute('aria-label','หมุดทดลอง: '+need.value+' '+count.value+' คน')};detail.append(form)}element.onclick=renderHelp;renderHelp()}
